def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: dict[str, bool] = {}
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(s: str) -> int | None:
        if s.isascii() and s.isdigit():
            return int(s)
        return None

    for idx, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0]

        if verb == "open" and len(parts) == 3:
            acc, amt = parts[1], parse_amount(parts[2])
            if amt is not None and acc not in balances:
                balances[acc] = amt
                frozen[acc] = False
                history.append(("open", acc))
            else:
                rejected.append(idx)

        elif verb == "deposit" and len(parts) == 3:
            acc, amt = parts[1], parse_amount(parts[2])
            if amt is not None and amt > 0 and acc in balances:
                balances[acc] += amt
                history.append(("deposit", acc, amt))
            else:
                rejected.append(idx)

        elif verb == "withdraw" and len(parts) == 3:
            acc, amt = parts[1], parse_amount(parts[2])
            if (
                amt is not None
                and amt > 0
                and acc in balances
                and not frozen[acc]
                and balances[acc] >= amt
            ):
                balances[acc] -= amt
                history.append(("withdraw", acc, amt))
            else:
                rejected.append(idx)

        elif verb == "transfer" and len(parts) == 4:
            src, dst, amt = parts[1], parts[2], parse_amount(parts[3])
            if (
                amt is not None
                and amt > 0
                and src != dst
                and src in balances
                and dst in balances
                and not frozen[src]
                and balances[src] >= amt
            ):
                balances[src] -= amt
                balances[dst] += amt
                history.append(("transfer", src, dst, amt))
            else:
                rejected.append(idx)

        elif verb == "freeze" and len(parts) == 2:
            acc = parts[1]
            if acc in balances and not frozen[acc]:
                frozen[acc] = True
                history.append(("freeze", acc))
            else:
                rejected.append(idx)

        elif verb == "unfreeze" and len(parts) == 2:
            acc = parts[1]
            if acc in balances and frozen[acc]:
                frozen[acc] = False
                history.append(("unfreeze", acc))
            else:
                rejected.append(idx)

        elif verb == "undo" and len(parts) == 1:
            if not history:
                rejected.append(idx)
            else:
                entry = history.pop()
                kind = entry[0]
                if kind == "open":
                    del balances[entry[1]]
                    del frozen[entry[1]]
                elif kind == "deposit":
                    balances[entry[1]] -= entry[2]
                elif kind == "withdraw":
                    balances[entry[1]] += entry[2]
                elif kind == "transfer":
                    balances[entry[1]] += entry[3]
                    balances[entry[2]] -= entry[3]
                elif kind == "freeze":
                    frozen[entry[1]] = False
                elif kind == "unfreeze":
                    frozen[entry[1]] = True

        else:
            rejected.append(idx)

    return balances, rejected
